const TYPING_TAGS=new Set(["INPUT","TEXTAREA","SELECT"]);export function isTypingTarget(target){if(target===null||typeof target!=="object")return false;const element=target;const tag=typeof element.tagName==="string"?element.tagName.toUpperCase():"";return TYPING_TAGS.has(tag)||element.isContentEditable===true;}
export function isShortcutsShortcut(event){return event.key==="?"&&event.metaKey!==true&&event.ctrlKey!==true&&event.altKey!==true;}
export function activate(parts,env){const{dialog,close}=parts;let opener=null;dialog.hidden=false;close?.addEventListener("click",()=>dialog.close());env.document.addEventListener("keydown",(event)=>{if(!isShortcutsShortcut(event))return;if(isTypingTarget(event.target))return;if(dialog.open)return;event.preventDefault();event.stopPropagation?.();opener=env.document.activeElement;dialog.showModal();},{capture:true},);dialog.addEventListener("keydown",(event)=>{if(event.key!=="Escape")return;event.preventDefault();event.stopPropagation?.();dialog.close();});dialog.addEventListener("close",()=>{const target=opener;opener=null;target?.focus();});}
if(typeof document!=="undefined"){const dialog=document.querySelector("[data-shortcuts]");const close=document.querySelector("[data-shortcuts] [data-shortcuts-close]");if(dialog){activate({dialog:dialog,...(close?{close:close}:{}),},{document},);}}